proc main(...argv: List[Str]) [fs, error] {
  let root = Path(argv[0])
  let n = if argv.len() >= 2 {
    argv[1].parse_uint()?
  } else {
    5
  }
  let top = fs.files(root, hidden: true, stat: true)?
    |> sort-by --desc { |e|
      e.size
    }
    |> take(n)
    |> collect()
  for item in top {
    print $item.size $item.path.display()
  }
}
